using System.Collections.Concurrent;
using System.Text.Json;
var data=new ConcurrentQueue<object>();
var b=WebApplication.CreateBuilder(args); b.WebHost.UseUrls("http://0.0.0.0:8765"); var app=b.Build();
app.MapGet("/",()=>Results.Content(@"<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>NAZIR Wi-Fi Motion Lab</title><style>body{background:#0d1220;color:#eef;padding:24px;font:16px Arial}main{max-width:850px;margin:auto}section{background:#19233a;padding:18px;border-radius:14px;margin:14px 0}.big{font-size:42px}canvas{width:100%;height:220px}</style></head><body><main><h1>NAZIR / WI-FI MOTION LAB</h1><section>Latest RSSI<div class='big' id='v'>Waiting…</div><div id='t'></div></section><section><canvas id='c' width='800' height='220'></canvas></section><p>RSSI changes do not prove movement and cannot identify or count people. Experimental signal monitor only.</p></main><script>let d=[];async function u(){try{d=await(await fetch('/data')).json();if(d.length){v.textContent=d[d.length-1].rssi+' dBm';t.textContent=new Date(d[d.length-1].time).toLocaleString()}let x=c.getContext('2d');x.clearRect(0,0,800,220);x.beginPath();x.strokeStyle='#70a5ff';d.slice(-100).forEach((p,i)=>{let a=i/99*800,b=(p.rssi+100)*2.2;i?x.lineTo(a,b):x.moveTo(a,b)});x.stroke()}catch(e){}}setInterval(u,2000);u();</script></body></html>","text/html"));
app.MapPost("/sample",async (HttpContext c)=>{using var j=await JsonDocument.ParseAsync(c.Request.Body);int r=j.RootElement.GetProperty("rssi").GetInt32();if(r < -100 || r > 0)return Results.BadRequest();data.Enqueue(new{rssi=r,time=DateTimeOffset.Now});while(data.Count>300)data.TryDequeue(out _);return Results.Ok();});
app.MapGet("/data",()=>Results.Json(data.ToArray())); app.Run();
